"""A defence summon battle's command box must route to the egg battle owner.

g1190 2026-11-18 04:55-07:25: the box もうこうげき / たまごをつかう / grey
きりふだ sat over the live monster panel. The pixel read set mixed_item_box,
which classify_text returned as battle_menu *before* the egg rules below could
run, so a generic A pressed the grey row for 2.5 h (#4528).
"""
from docich.hanjuku_speedrun.hanjuku.os_layer.font import TextLine
from docich.hanjuku_speedrun.hanjuku.os_layer.screen import EggRow, Screen, classify_text


def box(*, mixed=True, egg=True):
    rows = ((176, 'もうこうげき'), (192, 'たまごをつかう'))
    screen = Screen([], None, ''.join(label for _, label in rows))
    screen.menu_rows = [
        TextLine(y, tuple((176 + 8 * i, ch) for i, ch in enumerate(label)))
        for y, label in rows]
    screen.menu_cursor = 208
    screen.mixed_item_box = mixed
    screen.egg_rows = ([EggRow('ブラウニー', 5, 'ally', 180),
                        EggRow('テュポーン', 8, 'enemy', 200)] if egg else [])
    return screen


def test_defence_summon_box_reads_as_egg_battle_menu():
    assert classify_text(box()) == 'egg_battle_menu'


def test_kit_read_box_without_a_monster_stays_battle_menu():
    # #4456: the same foreground rows over no monster panel are the read-only
    # defence kit flow, which battle_menu_step owns. Do not steal that box.
    assert classify_text(box(egg=False)) == 'battle_menu'


def test_a_box_without_the_pixel_flag_keeps_the_existing_egg_rule():
    assert classify_text(box(mixed=False)) == 'egg_battle_menu'


def test_defence_summon_egg_moves_up_from_disabled_card():
    from docich.hanjuku_speedrun.hanjuku.flows.battle_menus import egg_battle_step

    screen = box()
    screen.kind = classify_text(screen)
    mem = {'egg_battle': True, 'egg_action': 'use_egg', 'egg_menu_stage': 2}
    assert [a['buttons'] for a in egg_battle_step(screen, mem)] == [['up']]
    screen.menu_cursor = 192
    assert [a['buttons'] for a in egg_battle_step(screen, mem)] == [['a']]


def test_defence_summon_egg_holds_when_cursor_unread():
    from docich.hanjuku_speedrun.hanjuku.flows.battle_menus import egg_battle_step

    screen = box()
    screen.kind = classify_text(screen)
    screen.menu_cursor = None
    mem = {'egg_battle': True, 'egg_action': 'use_egg', 'egg_menu_stage': 2}
    assert egg_battle_step(screen, mem) == []


def test_crying_summon_box_stays_battle_menu_and_attacks_in_active_battle():
    from docich.hanjuku_speedrun.hanjuku.flows.battle_menus import battle_menu_step
    from docich.hanjuku_speedrun.hanjuku.os_layer.commands import pad

    rows = [
        TextLine(192, tuple((176 + 8 * i, ch) for i, ch in enumerate('こうげき'))),
        TextLine(208, tuple((176 + 8 * i, ch) for i, ch in enumerate('たいきゃく'))),
    ]
    screen = Screen(rows, None, 'こうげきたいきゃく')
    screen.menu_rows = rows
    screen.menu_cursor = 192
    screen.egg_rows = [EggRow('ペコリーノ', 88, 'ally', 176),
                       EggRow('キャンドロー', 231, 'enemy', 200)]
    screen.kind = classify_text(screen)
    assert screen.kind == 'battle_menu'
    mem = {
        'indep_menu': True,
        'indep_menu_action': 'pass',
        'battle': {'ally': 'ペコリーノ', 'enemy': 'ヘーゼル',
                   'ally_hp': 88, 'enemy_hp': 14},
        '_records': [],
    }
    assert battle_menu_step(screen, mem) == [pad('a')]
    assert mem['_records'][-1]['decision'] == 'battle_menu_plain_command'
    screen.menu_cursor = 208
    assert battle_menu_step(screen, mem) == [pad('up')]


